ALTER TABLE {{DATA}}.devices ALTER COLUMN device_id COMMENT 'Device record ID';
ALTER TABLE {{DATA}}.devices ALTER COLUMN imei COMMENT '15-digit IMEI of the device (first 8 digits = type allocation code of the model)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN oem COMMENT 'Device manufacturer (Apple, Samsung, Google, Motorola)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN model COMMENT 'Marketing model name';
ALTER TABLE {{DATA}}.devices ALTER COLUMN model_family COMMENT 'Model family (iPhone, Galaxy S, Galaxy Z, Pixel, ...)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN storage_gb COMMENT 'Storage capacity in GB';
ALTER TABLE {{DATA}}.devices ALTER COLUMN born_on_date COMMENT 'Manufacture / activation date of the device';
ALTER TABLE {{DATA}}.devices ALTER COLUMN device_age_months COMMENT 'Device age in months when received';
ALTER TABLE {{DATA}}.devices ALTER COLUMN previous_owners COMMENT 'Number of previous owners / lifecycles this device has been through';
ALTER TABLE {{DATA}}.devices ALTER COLUMN customer_id COMMENT 'Platform customer whose program sent the device (FK customers)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN program COMMENT 'Recovery program: Trade-in, Insurance claim, Warranty return, Lease return, Buyback';
ALTER TABLE {{DATA}}.devices ALTER COLUMN facility_id COMMENT 'Processing facility (FK facilities)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN received_date COMMENT 'Date the device was received at the processing facility';
ALTER TABLE {{DATA}}.devices ALTER COLUMN functional_status COMMENT 'Functional grade from automated diagnostics: Fully functional, Minor defect, Major defect, No power';
ALTER TABLE {{DATA}}.devices ALTER COLUMN primary_defect COMMENT 'Main failed component from diagnostics (null if fully functional or no power)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN cosmetic_grade COMMENT 'Cosmetic grade on arrival from automated vision grading: A (like new), B, C, D (heavy damage)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN battery_health_pct COMMENT 'Battery state of health % on arrival. EU resale requires >= 80%';
ALTER TABLE {{DATA}}.devices ALTER COLUMN battery_replaced COMMENT 'True if the battery was previously replaced';
ALTER TABLE {{DATA}}.devices ALTER COLUMN oem_parts_only COMMENT 'True if the device arrived with only OEM (original manufacturer) parts';
ALTER TABLE {{DATA}}.devices ALTER COLUMN genuine_status COMMENT 'Genuine or Counterfeit, from OEM data plus device sensing';
ALTER TABLE {{DATA}}.devices ALTER COLUMN blacklist_status COMMENT 'Clean, Lost/stolen, or Unpaid balance (carrier/financing blacklist)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN next_best_action COMMENT 'Routing decision from the next-best-action model: Resell as-is, Buff & polish, Repair, Harvest parts, Recycle, Quarantine';
ALTER TABLE {{DATA}}.devices ALTER COLUMN repair_id COMMENT 'Repair order ID if routed to repair (FK repair_orders)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN dock_to_stock_hours COMMENT 'Hours from receiving dock to graded and sellable stock (processing speed)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN cosmetic_grade_final COMMENT 'Cosmetic grade after buff & polish or repair';
ALTER TABLE {{DATA}}.devices ALTER COLUMN battery_health_final COMMENT 'Battery health % after any battery repair';
ALTER TABLE {{DATA}}.devices ALTER COLUMN oem_parts_final COMMENT 'True if the device still has only OEM parts after repair';
ALTER TABLE {{DATA}}.devices ALTER COLUMN eu_market_eligible COMMENT 'True if the device meets EU resale requirements: battery >= 80%, OEM parts only, grade A/B, genuine and clean';
ALTER TABLE {{DATA}}.devices ALTER COLUMN value_as_received COMMENT 'Estimated market value in USD as graded on arrival';
ALTER TABLE {{DATA}}.devices ALTER COLUMN action_cost COMMENT 'Total cost of the next best action in USD (polish, repair, logistics and rework)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN value_recovered COMMENT 'Realized resale or salvage value in USD after the action and sales channel (null until completed)';
ALTER TABLE {{DATA}}.devices ALTER COLUMN net_value_lift COMMENT 'value_recovered minus action_cost minus value_as_received, in USD: value created by the next best action and channel decision';
ALTER TABLE {{DATA}}.devices ALTER COLUMN disposition_channel COMMENT 'Where the device went: Resold - US/EU, Exported - EU/LATAM/Africa/APAC, Recycled, Parts harvested, Quarantined, Pending';
ALTER TABLE {{DATA}}.devices ALTER COLUMN processing_status COMMENT 'Completed, In repair, or Grading';
ALTER TABLE {{DATA}}.devices ALTER COLUMN completed_date COMMENT 'Date the device left processing (sold, recycled or quarantined)';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN repair_id COMMENT 'Repair order ID';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN device_id COMMENT 'Device record ID (FK devices)';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN partner_id COMMENT 'Repair partner (FK repair_partners)';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN repair_type COMMENT 'Repair performed: Display, Battery, Back glass, Charging port, Camera, Audio, Biometrics, Board-level';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN parts_type COMMENT 'OEM or Aftermarket replacement parts. Aftermarket parts make the device ineligible for EU resale and reduce value ~12%';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN sent_date COMMENT 'Date sent to the repair partner';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN returned_date COMMENT 'Date returned from the repair partner';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN turnaround_days COMMENT 'Days the device was out at the repair partner (including rework if bounced)';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN repair_status COMMENT 'Completed or In progress';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN qa_result COMMENT 'Pass, or Bounce = failed QA on return and was reworked in-house';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN repair_cost COMMENT 'Partner repair charge in USD';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN logistics_cost COMMENT 'Round-trip shipping cost to the partner in USD';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN rework_cost COMMENT 'In-house rework cost in USD when the repair bounced';
ALTER TABLE {{DATA}}.repair_orders ALTER COLUMN value_erosion COMMENT 'Market value lost in USD while the device was out of inventory at the partner (time value of the device)';
